using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioDefaultShaderValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static AnimationStudioWindow host;static Material original;static int checks;static double ready;
 static string PathFor(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name));static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{var globalType=Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineGlobalSettings, Unity.RenderPipelines.HighDefinition.Runtime");globalType.GetMethod("Ensure",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{true});var pipeline=(RenderPipelineAsset)ScriptableObject.CreateInstance(Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineAsset, Unity.RenderPipelines.HighDefinition.Runtime"));AssetDatabase.CreateAsset(pipeline,AssetDatabase.GenerateUniqueAssetPath("Assets/StudioShaderValidationPipeline.asset"));GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;Check(GraphicsSettings.currentRenderPipeline&&GraphicsSettings.currentRenderPipeline.GetType().Name.Contains("HDRenderPipeline"),"HDRP pipeline active");var shader=AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath("409bba92b9fbb904cbfd7cf58b9531a6"));Check(shader&&!ShaderUtil.ShaderHasError(shader),"Graph imports and compiles");doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Sphere,out var polygons);original=new Material(GraphicsSettings.currentRenderPipeline.defaultMaterial);doc.nodes.Add(new StudioModelDocument.Node{name="Studio default",mesh=mesh,materials=new[]{original},cutPolygons=polygons,cutTriangles=mesh.triangles});doc.lighting.studioLights=true;doc.lighting.ground=false;doc.lighting.exposure=0;AnimationStudioWindow.Open();host=Resources.FindObjectsOfTypeAll<AnimationStudioWindow>().First();typeof(AnimationStudioWindow).GetMethod("SwitchStudioMode",F).Invoke(host,new object[]{true});typeof(AnimationStudioWindow).GetMethod("LoadStudioModel",F).Invoke(host,new object[]{doc});editor=host.ToolbarModelEditor;editor.SetDisplayMode(true,false);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().First(v=>v.Studio==host);view.position=new Rect(60,60,800,650);view.LookAtDirect(Vector3.zero,Quaternion.Euler(20,35,0),2);ready=EditorApplication.timeSinceStartup+3;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static Color32[] Render(string file=null){var rt=new RenderTexture(320,320,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);rt.Create();var old=RenderTexture.active;var image=new Texture2D(320,320,TextureFormat.RGBA32,false);try{RenderPipeline.SubmitRenderRequest(view.camera,new RenderPipeline.StandardRequest{destination=rt});RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,320,320),0,0);image.Apply();if(file!=null)File.WriteAllBytes(PathFor(file),image.EncodeToPNG());return image.GetPixels32();}finally{RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<ready)return;EditorApplication.update-=Tick;try{var shader=AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath("409bba92b9fbb904cbfd7cf58b9531a6"));var renderer=editor.Transforms[0].GetComponent<Renderer>();var material=renderer.sharedMaterial;Check(material.shader==shader,"Existing renderer uses designated graph");var defaultTemplate=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath("410de6c3c565a5b459045246f998f390"));var xrayTemplate=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath("0d08d9ca74c59e940a654b9ca078d478"));Check(defaultTemplate&&xrayTemplate,"Both material templates load");Check(xrayTemplate.shader.name=="MashBox/Studio/Preview","Xray asset resolves visible shader name");Check(Shader.Find("MashBox/Studio/Preview")==xrayTemplate.shader,"Preview shader discoverable by new name");Check(!ReferenceEquals(material,defaultTemplate)&&material.parent==defaultTemplate&&material.isVariant,"Default preview is a transient Material Variant");var originalTint=defaultTemplate.GetColor("_BaseColor");var originalSmooth=defaultTemplate.GetVector("_SmoothnessRemap");try{defaultTemplate.SetColor("_BaseColor",new Color(.3f,.4f,.5f));defaultTemplate.SetVector("_SmoothnessRemap",new Vector4(.2f,.2f,0,0));Check(ReferenceEquals(renderer.sharedMaterial,material)&&material.GetColor("_BaseColor")==new Color(.3f,.4f,.5f)&&material.GetVector("_SmoothnessRemap")==new Vector4(.2f,.2f,0,0),"Parent color and smoothness edits propagate to existing child without recreation");}finally{defaultTemplate.SetColor("_BaseColor",originalTint);defaultTemplate.SetVector("_SmoothnessRemap",originalSmooth);editor.SetDisplayMode(true,false);}material=renderer.sharedMaterial;Check(material.HasProperty("_BaseColorMap"),"Base map exposed for future UV grid");Check(material.renderQueue<(int)RenderQueue.Transparent,"Neutral graph remains opaque");var get=typeof(StudioModelEditor).GetMethod("DisplayMaterial",F);Check(ReferenceEquals(get.Invoke(editor,new object[]{original,0}),material),"Repeated draw reuses preview material");Check(material.GetColor("_BaseColor")==new Color(.65f,.65f,.65f),"Neutral gray retained");Check(material.GetVector("_MetallicRemap")==Vector4.zero&&material.GetVector("_SmoothnessRemap")==Vector4.zero,"Matte nonmetallic remaps retained");var visible=Render("studio-default-graph.png");renderer.forceRenderingOff=true;var background=Render();renderer.forceRenderingOff=false;Check(visible.Zip(background,(a,b)=>a.Equals(b)?0:1).Sum()>100,"HDRP renderer visibly draws graph geometry");Check(visible.Count(c=>c.r>180&&c.b>180&&c.g<50)<20,"No magenta shader-error surface");var originalOpacity=xrayTemplate.GetFloat("_Opacity");try{editor.SetXRayMode(true);var child=renderer.sharedMaterial;xrayTemplate.SetFloat("_Opacity",.38f);Check(child.parent==xrayTemplate&&child.isVariant&&ReferenceEquals(renderer.sharedMaterial,child)&&Mathf.Abs(child.GetFloat("_Opacity")-.38f)<.0001f,"Xray parent opacity propagates to existing variant");var parentColor=xrayTemplate.GetColor("_Color");try{xrayTemplate.SetColor("_Color",Color.cyan);Check(child.GetColor("_Color")==Color.cyan,"Xray tint inherited without a baked child override");}finally{xrayTemplate.SetColor("_Color",parentColor);}var transparent=Render("studio-xray-material.png");Check(!visible.SequenceEqual(transparent),"Xray template changes rendered output");}finally{xrayTemplate.SetFloat("_Opacity",originalOpacity);editor.SetXRayMode(false);}editor.SetXRayMode(true);Check(renderer.sharedMaterial.shader!=shader&&renderer.sharedMaterial.renderQueue>=(int)RenderQueue.Transparent,"Xray keeps separate transparent preview");editor.SetXRayMode(false);editor.SetDisplayMode(false,false);Check(renderer.sharedMaterial.shader!=shader,"Lighting-off retains unlit preview");editor.SetDisplayMode(true,true);Check(renderer.sharedMaterial.shader==original.shader,"Textures-on restores source shader");Check(ReferenceEquals(doc.nodes[0].materials[0],original),"Source material assignment unchanged");Finish("PASS "+checks+" default graph selection/render checks");}catch(Exception e){Finish(e.ToString());}}
 sealed class MaterialScope:IDisposable{internal Material Value;internal MaterialScope(Shader s){Value=new Material(s);}public void Dispose(){Object.DestroyImmediate(Value);}}
 static void Finish(string result){EditorApplication.update-=Tick;File.WriteAllText(PathFor("studio-default-shader-result.txt"),result);EditorApplication.Exit(result.StartsWith("PASS")?0:1);}
}
